// i18n under the deploy subpath: mirrors the GitHub Pages project site,
// where the site lives under /wiki/ (fixture built by tests/setup-subpath.js,
// served by tests/serve.js). Regression coverage for the bug where the
// runtime language code (static/i18n.js, generated by tools/gen_i18n.py)
// assumed the site at the domain root: URL language detection, switcher
// navigation, and nav-link rewriting must all respect the /wiki base path.
const { test, expect } = require('@playwright/test');

test.describe('i18n under the /wiki subpath', () => {
  async function clearLang(page) {
    await page.evaluate(() => localStorage.removeItem('wiki-lang'));
  }

  test('translated page: chrome is translated + lang detected from the URL', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/fr/`);
    // Language detected from /wiki/fr/ (not just localStorage)
    await expect(page.locator('html')).toHaveAttribute('lang', 'fr');
    await expect(page.locator('.mode-tab[data-mode-tab="home"]')).toContainText('Accueil');
    await expect(page.locator('#wiki-search')).toHaveAttribute('placeholder', /Rechercher/);
    // i18n.js finished applying the translation
    expect(await page.evaluate(() =>
      document.documentElement.hasAttribute('data-i18n-pending'))).toBe(false);
  });

  test('switching to French from the subpath root navigates to /wiki/fr/', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/`);
    await clearLang(page);
    await page.reload();
    const nav = page.waitForNavigation({ waitUntil: 'domcontentloaded' });
    await page.locator('#lang-toggle').click();
    await page.locator('#lang-menu button[data-lang="fr"]').click();
    await nav;
    await expect(page).toHaveURL(/\/wiki\/fr\/$/);
    await expect(page.locator('.mode-tab[data-mode-tab="home"]')).toContainText('Accueil');
  });

  test('switching back to English from a French page navigates to /wiki/', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/fr/`);
    await page.evaluate(() => localStorage.setItem('wiki-lang', 'fr'));
    await page.reload();
    const nav = page.waitForNavigation({ waitUntil: 'domcontentloaded' });
    await page.locator('#lang-toggle').click();
    await page.locator('#lang-menu button[data-lang="en"]').click();
    await nav;
    await expect(page).toHaveURL(/\/wiki\/$/);
    await expect(page.locator('.mode-tab[data-mode-tab="home"]')).toContainText('Home');
  });

  test('switching on a page WITHOUT a translation swaps chrome only', async ({ page, baseURL }) => {
    // /content/items/titanium/ has no French equivalent
    await page.goto(`${baseURL}/content/items/titanium/`);
    await clearLang(page);
    await page.reload();
    await page.locator('#lang-toggle').click();
    await page.locator('#lang-menu button[data-lang="fr"]').click();
    await page.waitForTimeout(300);
    expect(page.url()).not.toMatch(/\/fr\//);
    await expect(page.locator('.mode-tab[data-mode-tab="home"]')).toContainText('Accueil');
    await expect(page.locator('html')).toHaveAttribute('lang', 'fr');
    await expect(page.locator('h1')).toContainText('Titanium');
  });

  test('nav links are rewritten with the /wiki/<lang> prefix (no bare /<lang> links)', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/fr/features/combat/`);
    await page.waitForTimeout(500);

    // Home link: /wiki/fr/ (not /fr/, which would 404 on the project site)
    await expect(page.locator('.mode-tab[data-mode-tab="home"]')).toHaveAttribute('href', '/wiki/fr/');
    const gs = page.locator('.nav-items a[href*="getting-started"]');
    await expect(gs).toHaveAttribute('href', '/wiki/fr/features/getting-started/');

    // No site link may point outside the /wiki base (that is a 404 on Pages)
    const bad = await page.evaluate(() =>
      Array.from(document.querySelectorAll('.sidenav a, .footnav a, .home-card, .brand, main a'))
        .map(a => a.getAttribute('href'))
        .filter(h => h && h.startsWith('/') && !h.startsWith('/wiki/')));
    expect(bad).toEqual([]);
  });

  test('English page with Russian saved: nav links stay under /wiki/', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/`);
    await page.evaluate(() => localStorage.setItem('wiki-lang', 'ru'));
    await page.reload();
    await page.waitForTimeout(300);

    const startLink = page.locator('.nav-group-link[href*="start"]');
    await expect(startLink).toHaveAttribute('href', '/wiki/ru/menu/start/');
    const nav = page.waitForNavigation({ waitUntil: 'domcontentloaded' });
    await startLink.click();
    await nav;
    await expect(page).toHaveURL(/\/wiki\/ru\/menu\/start\/$/);
    await expect(page.locator('h1')).toContainText('Начало игры');
  });

  test('search results link under the subpath', async ({ page, baseURL }) => {
    await page.goto(`${baseURL}/`);
    await page.locator('#wiki-search').fill('ores');
    const first = page.locator('#search-results a').first();
    await expect(first).toBeVisible();
    const href = await first.getAttribute('href');
    expect(href).toMatch(/^\/wiki\//);
  });

  test('no flash of English on translated pages (head detection under subpath)', async ({ page, baseURL }) => {
    // The head script must detect the language from /wiki/fr/... BEFORE first
    // paint: it strips the deploy base (config.base_url) before matching.
    await page.goto(`${baseURL}/fr/features/combat/`);
    const lang = await page.evaluate(() => document.documentElement.getAttribute('lang'));
    expect(lang).toBe('fr');
    const homeLabel = await page.locator('.mode-tab[data-mode-tab="home"] span[data-i18n="nav_home"]').textContent();
    expect(homeLabel).not.toBe('Home');
  });
});
